1072	    #[test]
1073	    fn vfs_write_payload_offsets_are_ordered_and_disjoint() {
1074	        // Every field the request defines, in declaration order, with its width:
1075	        // the i32 fields are 4 bytes, the u64 buffer address is 8.
1076	        //
1077	        // Unlike `CDEV_WRITE` this payload carries a raw buffer address rather
1078	        // than a grant id — VFS's client is an ordinary user process with no
1079	        // grant table. VFS makes the grant itself, naming the caller's buffer,
1080	        // and takes the owner from the kernel-stamped `m_source`. There is
1081	        // deliberately no owner/granter field here for the same reason there is
1082	        // none in `CDEV_WRITE`: VFS holds `SYS_PROC`, so a caller-supplied owner
1083	        // would aim a privileged cross-address-space copy at a third party.
1084	        let fields = [
1085	            ("fd", VFS_FD_OFF, 4),
1086	            ("len", VFS_LEN_OFF, 4),
1087	            ("buf", VFS_BUF_OFF, 8),
1088	        ];
1089	        assert_eq!(fields.len(), 3, "a VFS_WRITE payload field was added");
1090	        assert_eq!(VFS_FD_OFF, 0, "the first field must start the payload");
1091	
1092	        for pair in fields.windows(2) {
1093	            let (name, off, width) = pair[0];
1094	            let (next_name, next_off, _) = pair[1];
1095	            assert!(
1096	                off + width <= next_off,
1097	                "{name} ({off}..{}) overlaps {next_name} at {next_off}",
1098	                off + width,
1099	            );
1100	        }
1101	        let (last_name, last_off, last_width) = fields[fields.len() - 1];
1102	        assert!(
1103	            last_off + last_width <= 96,
1104	            "{last_name} runs past the 96-byte payload",
1105	        );
1106	
1107	        // The u64 field must be 8-aligned *within the message*, whose payload
1108	        // starts at byte 8 — so an even multiple of 8 here.
1109	        assert_eq!((8 + VFS_BUF_OFF) % 8, 0);
1110	    }
