3	//! Process counts and well-known endpoints.
4	//!
5	//! Kernel tasks (`ASYNCM`, `IDLE`, `CLOCK`, `SYSTEM`, `HARDWARE`) live at
6	//! negative process numbers; system servers and other user-space processes
7	//! live at non-negative process numbers in the order they boot. The set of
8	//! kernel tasks follows MINIX 3 `include/minix/com.h`; the user-space proc
9	//! numbering does not — see the boot-image section below.
10	
11	use crate::endpoint::{ENDPOINT_SLOT_TOP, Endpoint, ProcNr, make_endpoint};
12	
13	/// Number of kernel tasks (slots with negative proc-numbers).
14	pub const NR_TASKS: usize = 5;
15	/// Number of user-process slots in the process table.
16	pub const NR_PROCS: usize = 1024;
17	/// Number of slots in the privilege table — system (privileged) processes.
18	pub const NR_SYS_PROCS: usize = 64;
19	
20	// NR_PROCS must not grow into the sentinel range (ANY/NONE/SELF live at
21	// ENDPOINT_SLOT_TOP, -1, -2). Raising NR_PROCS past this bound would alias
22	// a real endpoint with a sentinel.
23	const _: () = assert!(NR_PROCS < (ENDPOINT_SLOT_TOP.get() as usize) - 2);
24	
25	// ---------------------------------------------------------------------------
26	// Kernel tasks — negative proc-numbers.
27	// ---------------------------------------------------------------------------
28	
29	/// Asynchronous-message driver (kernel pseudo-task).
30	pub const ASYNCM: ProcNr = ProcNr::new(-5);
31	/// Idle task (runs when nothing else is runnable).
32	pub const IDLE: ProcNr = ProcNr::new(-4);
33	/// Clock task (kernel pseudo-task for timer-driven work).
34	pub const CLOCK: ProcNr = ProcNr::new(-3);
35	/// System task (handles `SYS_*` kernel calls).
36	pub const SYSTEM: ProcNr = ProcNr::new(-2);
37	/// Hardware-interrupt pseudo-task (source endpoint for IRQ notifications).
38	pub const HARDWARE: ProcNr = ProcNr::new(-1);
39	
40	// ---------------------------------------------------------------------------
41	// Well-known user-space servers — generation 0 at boot.
42	//
43	// minix.rs boot image: renumbered contiguously from 0. Differs from MINIX
44	// 3, which scatters slots (no slot 7) and places SCHED at 4. LOG is not
45	// statically slotted in minix.rs — RS spawns it on demand.
46	// ---------------------------------------------------------------------------
47	
48	pub const PM_PROC_NR: ProcNr = ProcNr::new(0);
49	pub const VFS_PROC_NR: ProcNr = ProcNr::new(1);
50	pub const RS_PROC_NR: ProcNr = ProcNr::new(2);
51	pub const MEM_PROC_NR: ProcNr = ProcNr::new(3);
52	pub const TTY_PROC_NR: ProcNr = ProcNr::new(4);
53	pub const DS_PROC_NR: ProcNr = ProcNr::new(5);
54	pub const MFS_PROC_NR: ProcNr = ProcNr::new(6);
55	pub const VM_PROC_NR: ProcNr = ProcNr::new(7);
56	pub const PFS_PROC_NR: ProcNr = ProcNr::new(8);
57	pub const SCHED_PROC_NR: ProcNr = ProcNr::new(9);
58	pub const INIT_PROC_NR: ProcNr = ProcNr::new(10);
59	
60	/// One past the highest boot-server proc-number (`init` is the last slot
61	/// allocated from the boot image).
62	pub const NR_BOOT_PROCS: usize = (INIT_PROC_NR.get() as usize) + 1;
63	
64	// Compile-time guarantees that the proc tables can hold every boot process.
65	const _: () = assert!(NR_PROCS >= NR_BOOT_PROCS);
66	const _: () = assert!(NR_SYS_PROCS >= NR_BOOT_PROCS);
67	
68	// ---------------------------------------------------------------------------
69	// Phase-4 demo stubs — hand-installed EL0 programs just past the boot image.
70	//
71	// Slices 2.x-4.x install tiny assembly stubs (kernel `arch::aarch64::userland`)
72	// as live exercises for IPC, kernel calls, VM, and the PM signal path. PM's
73	// mproc table (slice 4.5) seeds them as user processes, so their proc numbers
74	// are shared here rather than kept kernel-private. Stub E — the fork/exec/wait
75	// demo — was retired in slice 4.8 when init (PID 1) took over that exercise as a
76	// real process; A–D remain as the live regression battery for the IPC
77	// primitives, SCHED delegation, and the VM page-fault / SIGSEGV paths, none of
78	// which init + worker exercise.
79	//
80	// Slots 11..=14 are reserved for the stubs regardless of the kernel/PM
81	// `boot-stubs` feature: with the feature on (default) they are installed and
82	// seeded, off they are simply left empty for a clean boot. `NR_STUB_PROCS` (and
83	// hence `FORK_POOL_BASE`) is constant either way, so forked-child proc numbers
84	// don't shift — only whether 11..=14 are occupied does.
85	// ---------------------------------------------------------------------------
86	
87	/// Stub A — SENDREC ping loop to stub B.
88	pub const STUB_A_PROC_NR: ProcNr = ProcNr::new(11);
89	/// Stub B — RECEIVE/SEND echo peer of stub A.
90	pub const STUB_B_PROC_NR: ProcNr = ProcNr::new(12);
91	/// Stub C — `SYS_GETINFO(GET_WHOAMI)` kernel-call loop (SCHED-delegated).
92	pub const STUB_C_PROC_NR: ProcNr = ProcNr::new(13);
93	/// Stub D — brk/mmap/munmap VM client; deliberately faults out-of-region
94	/// after its munmap (slice 4.5) to exercise the SIGSEGV → PM kill path.
95	pub const STUB_D_PROC_NR: ProcNr = ProcNr::new(14);
96	
97	/// Number of stub slots reserved just past the boot image (A–D; the fork-loop
98	/// stub E was retired in slice 4.8). Constant regardless of the `boot-stubs`
99	/// feature — the feature controls whether these slots are *occupied*, not the
100	/// reservation, so `FORK_POOL_BASE` (and forked-child proc numbers) stay stable.
101	pub const NR_STUB_PROCS: usize = 4;
102	
103	// Stubs sit contiguously just past the boot image, well inside the proc table.
104	const _: () = assert!(STUB_A_PROC_NR.get() as usize == NR_BOOT_PROCS);
105	const _: () = assert!(STUB_D_PROC_NR.get() as usize == NR_BOOT_PROCS + NR_STUB_PROCS - 1);
106	const _: () = assert!((STUB_D_PROC_NR.get() as usize) < NR_PROCS);
107	
108	/// Exclusive upper bound on the kernel proc numbers that the user-space servers
109	/// (PM, VM, SCHED) keep per-process state for. All three server tables are keyed
110	/// by proc number over the same range `[0, NR_SERVED_PROCS)` — the boot procs
111	/// `[0, NR_BOOT_PROCS)`, the demo-stub slots, and the fork pool
112	/// `[NR_BOOT_PROCS + NR_STUB_PROCS, NR_SERVED_PROCS)`. Sizing PM's `mproc` table,
113	/// VM's `ClientRegions` table, and SCHED's policy table from this one constant
114	/// (rather than three independent numbers that merely happen to agree) keeps
115	/// them from silently skewing. Bounded above by the kernel's user-proc range
116	/// (`NR_PROCS`); the fork pool must be non-empty above the boot + stub slots.
117	pub const NR_SERVED_PROCS: usize = 32;
118	
119	const _: () = assert!(NR_SERVED_PROCS <= NR_PROCS);
120	const _: () = assert!(NR_SERVED_PROCS > NR_BOOT_PROCS + NR_STUB_PROCS);
121	
122	/// Sentinel `proc_nr` for an MXBI archive module that is **not** a boot server:
123	/// it is packed only so `SYS_EXEC` can resolve it by name (slice 4.7's `worker`
124	/// binary), and the boot loader skips any module with a negative proc number
125	/// (it has no proc/priv slot to load into). `kernel/build.rs` tags such records
126	/// with this value; the kernel-side skip lives in `userland`'s load loop.
127	pub const EXEC_ONLY_PROC_NR: i32 = -1;
128	
129	/// Build a boot-time endpoint (generation 0) for a task or server.
130	pub const fn boot_endpoint(p: ProcNr) -> Endpoint {
131	    make_endpoint(0, p)
132	}
