57	/// The banner TTY writes straight to the UART once its device mapping is proven
58	/// usable from EL0.
59	///
60	/// This line is the slice's milestone, and it is recognizable in the boot log for a
61	/// specific reason: it carries **no kernel trace prefix**. Every other line in the
62	/// log is `[as]`, `[ipc]`, `[ksys …]`, `[diag …]` — kernel-formatted. This one was
63	/// composed at EL0 and reached the wire through a user-space store to a device
64	/// register.
65	const BANNER: &str = "minix.rs console: tty online (EL0)\n";
66	
67	/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start` can dive
68	/// straight into Rust without setting up a stack itself.
69	// Gate the whole shim to `not(test)`: under `cargo test` the crate links as a
70	// normal host executable, and an exported `_start` would collide with the C
71	// runtime's. `.text._start` is an ELF section name, gated to the minixrs target
72	// so `cargo check --workspace` on a Mach-O host still type-checks.
73	#[cfg(not(test))]
74	#[unsafe(no_mangle)]
75	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
76	pub extern "C" fn _start() -> ! {
77	    main()
78	}
79	
80	// Only `_start` calls `main`; under `cargo test` `_start` is gone, so `main` (and
81	// the helpers it alone reaches) would read as dead code.
82	#[cfg_attr(test, allow(dead_code))]
83	fn main() -> ! {
84	    let sef = sef_startup(SefConfig {
85	        init_fresh: Some(tty_init),
86	        signal_handler: None,
87	    })
88	    .unwrap_or_else(|_| {
89	        // No recovery and nothing to print: a failed handshake means TTY never
90	        // learned its own endpoint, so it cannot even announce the failure.
91	        loop {
92	            core::hint::spin_loop()
93	        }
94	    });
95	
96	    // The staging buffer lives in `main`'s frame, not in a static and not in
97	    // `tty_init`'s frame — the same rule `GrantPool` follows, and for the same
98	    // reason: the kernel writes into it while TTY is blocked inside the
99	    // `SYS_SAFECOPY` SENDREC, so the frame must outlive every call that names it.
100	    // One page of stack holds it comfortably at `CDEV_MAX_IO` = 256 bytes.
101	    let mut staging = [0u8; CDEV_MAX_IO];
102	
103	    let mut msg = Message {
104	        m_source: 0,
105	        m_type: 0,
106	        payload: [0u8; 96],
107	    };
108	    loop {
109	        if sef.receive(&mut msg) != OK {
110	            continue;
111	        }
112	        // Capture the caller *first*: it is both the reply target and the granter,
113	        // and the dispatch below overwrites `msg.m_source` on the way out.
114	        let caller_e = msg.m_source;
115	        match msg.m_type {
116	            CDEV_WRITE => {
117	                let rc = do_write(caller_e, &msg, &mut staging);
118	                reply(caller_e, &mut msg, rc);
119	            }
120	            // Unlike DS, reply rather than drop — the caller is inside a SENDREC
121	            // and would otherwise block forever.
122	            _ => reply(caller_e, &mut msg, ENOSYS),
123	        }
124	    }
125	}
126	
127	/// SEF fresh-init callback: publish to DS, then prove the device mapping.
128	///
129	/// Order matters for the boot log. `sef_startup` has already emitted
130	/// `[diag tty] sef ready` through the kernel debug channel, so by the time the
131	/// banner appears the two independent output paths — debug channel and real
132	/// console — have each been exercised once, and a failure in either is
133	/// distinguishable from a failure in the other.
134	///
135	/// If the *device mapping* were broken this never returns: the store faults, and
136	/// TTY has no `ipc_to` edge to VM's fault handler for a device VA, so the process
137	/// dies on an EL0 data abort that `tests/qemu-boot.forbidden` catches.
138	#[cfg_attr(test, allow(dead_code))]
139	fn tty_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
140	    let rc = sef_publish_to_ds(name);
141	    if rc != OK {
142	        return rc;
143	    }
144	    pl011::write(BANNER.as_bytes());
145	    OK
146	}
147	
148	/// Serve one `CDEV_WRITE`. Returns the reply `m_type`: the byte count written
149	/// (`>= 0`), or a negative errno.
150	///
151	/// `staging` is the caller's buffer, passed in rather than declared here so it
152	/// lives in `main`'s frame (see the comment at its declaration).
153	#[cfg_attr(test, allow(dead_code))]
154	fn do_write(caller_e: Endpoint, msg: &Message, staging: &mut [u8; CDEV_MAX_IO]) -> i32 {
155	    let req = cdev::parse_write(msg);
156	    let n = match cdev::validate_write(req) {
157	        Ok(n) => n,
158	        Err(e) => return e,
159	    };
160	    if n == 0 {
161	        // A legal zero-length write. No grant is read and nothing is transmitted,
162	        // so a client polling with `len = 0` cannot use it to probe a grant.
163	        return 0;
164	    }
165	
166	    // Pull the bytes across from the client's granted buffer. `caller_e` is the
167	    // kernel-stamped source of this very message — the granter can be nothing else.
168	    let rc = sys_safecopy(
169	        SAFECOPY_FROM,
170	        caller_e,
171	        req.gid,
172	        req.offset,
173	        buf_addr(&mut staging[..n]),
174	        n as u64,
175	    );
176	    if rc != OK {
177	        // Verbatim: EPERM and EFAULT tell the client different things.
178	        return rc;
179	    }
180	
181	    pl011::write(&staging[..n]);
182	    // The count actually moved, which is `CDEV_MAX_IO` for an over-long request.
183	    // Replying `OK` here instead would tell a client its whole buffer went out.
184	    n as i32
185	}
186	
187	/// Reply to a SENDREC caller: stamp `m_type`, zero `m_source` (the kernel
188	/// overwrites it on delivery), and SEND the message back.
189	#[cfg_attr(test, allow(dead_code))]
190	fn reply(target_e: Endpoint, msg: &mut Message, m_type: i32) {
191	    msg.m_type = m_type;
192	    msg.m_source = 0;
193	    let _ = ipc_send(target_e, msg);
194	}
195	
196	// The freestanding panic handler; under `cargo test` std supplies its own.
197	#[cfg(not(test))]
198	#[panic_handler]
199	fn panic(_: &core::panic::PanicInfo) -> ! {
200	    loop {
201	        core::hint::spin_loop()
202	    }
203	}
