3	//! Kernel-call clients for the cross-address-space copy engine (slice 5.2's
4	//! `SYS_SAFECOPY` / `SYS_COPY`).
5	//!
6	//! Lifted out of PM in slice 5.3, when the TTY driver became the second holder of
7	//! `SYS_SAFECOPY` and the marshaling would otherwise have been copied verbatim.
8	//! The payload layouts are documented on the two constants in
9	//! `kernel-shared::callnr`; this module is the single place they are written.
10	//!
11	//! Like [`crate::sef`], [`crate::ds`], and [`crate::diag`], these issue IPC traps,
12	//! so the module is excluded from host coverage and verified through the kernel's
13	//! `[ksys SYS_SAFECOPY]` / `[ksys SYS_COPY]` boot traces.
14	//!
15	//! ## The confused-deputy rule
16	//!
17	//! A server that holds these calls and serves clients that do not must take the
18	//! **granter from the kernel-stamped `m_source`**, never from a request payload. A
19	//! caller-supplied granter endpoint would let any client aim a privileged
20	//! cross-address-space copy at a third party's memory *through* the server. These
21	//! functions cannot enforce that — the granter is a parameter — so it is the
22	//! caller's obligation, and it binds every grant-id-carrying request in the CDEV,
23	//! BDEV, and FS bands.
24	
25	use minixrs_ipc::ipc_sendrec;
26	use minixrs_kernel_shared::callnr::{SYS_COPY, SYS_SAFECOPY};
27	use minixrs_kernel_shared::com::{SYSTEM, boot_endpoint};
28	use minixrs_kernel_shared::error::OK;
29	use minixrs_kernel_shared::{Endpoint, Message};
30	
31	use crate::payload::{wr_i32, wr_u64};
32	
33	/// `SYS_SAFECOPY` — copy between the range grant `gid` describes and the
34	/// caller's own buffer at `addr`.
35	///
36	/// `direction` is `SAFECOPY_FROM` (grant → caller) or `SAFECOPY_TO` (caller →
37	/// grant); `offset` is measured within the granted range, so a client can drive a
38	/// short-write loop by advancing it. `granter` must be the endpoint the *kernel*
39	/// stamped on the request being served — see the module docs.
40	///
41	/// Returns the kernel-call result: `OK`, or a negative errno. Callers should relay
42	/// a negative result **verbatim** rather than collapsing it, because the two
43	/// failures mean different things to the client: `EPERM` is "your grant does not
44	/// authorize this" and `EFAULT` is "your buffer is not mapped".
45	pub fn sys_safecopy(
46	    direction: i32,
47	    granter: Endpoint,
48	    gid: i32,
49	    offset: u64,
50	    addr: u64,
51	    bytes: u64,
52	) -> i32 {
53	    let mut m = Message {
54	        m_source: 0,
55	        m_type: SYS_SAFECOPY,
56	        payload: [0u8; 96],
57	    };
58	    wr_i32(&mut m, 0, direction);
59	    wr_i32(&mut m, 4, granter);
60	    wr_i32(&mut m, 8, gid);
61	    wr_u64(&mut m, 16, offset);
62	    wr_u64(&mut m, 24, addr);
63	    wr_u64(&mut m, 32, bytes);
64	    sendrec_to_system(&mut m)
65	}
66	
67	/// `SYS_COPY` — raw privileged copy from `(src_e, src_addr)` to
68	/// `(dst_e, dst_addr)`, with no grant involved. `SELF` names the caller.
69	///
70	/// There is no per-target authorization here at all: the caller's `k_call_mask`
71	/// bit *is* the whole check, the `SYS_VMCTL` trust stance. Only for small
72	/// control-plane reads on behalf of a caller the server already trusts.
73	pub fn sys_copy(src_e: Endpoint, src_addr: u64, dst_e: Endpoint, dst_addr: u64, bytes: u64) -> i32 {
74	    let mut m = Message {
75	        m_source: 0,
76	        m_type: SYS_COPY,
77	        payload: [0u8; 96],
78	    };
79	    wr_i32(&mut m, 0, src_e);
80	    wr_i32(&mut m, 4, dst_e);
81	    wr_u64(&mut m, 16, src_addr);
82	    wr_u64(&mut m, 24, dst_addr);
83	    wr_u64(&mut m, 32, bytes);
84	    sendrec_to_system(&mut m)
85	}
86	
87	/// SENDREC a prepared kernel call to `SYSTEM` and flatten the two failure routes.
88	///
89	/// A trap-level failure (the SENDREC itself was refused — no `ipc_to` bit, bad
90	/// endpoint) and a call-level failure (the kernel ran the call and rejected it)
91	/// arrive by different paths, so both are checked; the same two-step every other
92	/// `server-rt` client uses.
93	fn sendrec_to_system(m: &mut Message) -> i32 {
94	    let trap_rc = ipc_sendrec(boot_endpoint(SYSTEM), m);
95	    if trap_rc != OK {
96	        return trap_rc;
97	    }
98	    m.m_type
99	}
