3	//! SEF startup handshake and control-aware receive loop.
4	
5	use crate::diag::diag_print;
6	use minixrs_ipc::{ipc_notify, ipc_receive, ipc_sendrec};
7	use minixrs_kernel_shared::Message;
8	use minixrs_kernel_shared::callnr::{GET_WHOAMI, SYS_GETINFO, SYS_GETINFO_NAME_LEN};
9	use minixrs_kernel_shared::com::{RS_PROC_NR, SYSTEM, boot_endpoint};
10	use minixrs_kernel_shared::endpoint::{ANY, Endpoint};
11	use minixrs_kernel_shared::error::OK;
12	
13	use crate::classify::{SefEvent, classify};
14	use crate::init::SefInitCb;
15	use crate::signal::SefSignalCb;
16	
17	/// Callbacks a server registers with the framework at startup. Both are
18	/// optional: a server with no init work or no signal handling passes `None`.
19	pub struct SefConfig {
20	    /// Run once after the startup handshake (see [`SefInitCb`]).
21	    pub init_fresh: Option<SefInitCb>,
22	    /// Invoked for each delivered signal (see [`SefSignalCb`]).
23	    pub signal_handler: Option<SefSignalCb>,
24	}
25	
26	/// A live SEF session, returned by [`sef_startup`]. Carries the server's own
27	/// endpoint + name (learned via `GET_WHOAMI`) and its registered callbacks, so
28	/// [`Sef::receive`] needs no static state. Cheap to copy (an endpoint, a 16-byte
29	/// name, and a function pointer).
30	#[derive(Copy, Clone)]
31	pub struct Sef {
32	    endpoint: Endpoint,
33	    name: [u8; SYS_GETINFO_NAME_LEN],
34	    signal_handler: Option<SefSignalCb>,
35	}
36	
37	/// Perform the SEF startup handshake: learn the server's own endpoint and name
38	/// from the kernel via `SYS_GETINFO(GET_WHOAMI)` (a SENDREC to `SYSTEM`), then
39	/// run the registered fresh-init callback. Returns the [`Sef`] handle to drive
40	/// the receive loop, or a negative error code if the handshake or init failed.
41	pub fn sef_startup(cfg: SefConfig) -> Result<Sef, i32> {
42	    // SYS_GETINFO(GET_WHOAMI): request selector goes in payload[0..4]; the
43	    // kernel replies in-place with our endpoint (0..4), priv flags (4..8),
44	    // init flags (8..12), and name (12..28), setting m_type = OK.
45	    let mut msg = Message {
46	        m_source: 0,
47	        m_type: SYS_GETINFO,
48	        payload: [0u8; 96],
49	    };
50	    msg.payload[0..4].copy_from_slice(&GET_WHOAMI.to_ne_bytes());
51	
52	    let trap_rc = ipc_sendrec(boot_endpoint(SYSTEM), &mut msg);
53	    if trap_rc != OK {
54	        return Err(trap_rc);
55	    }
56	    if msg.m_type != OK {
57	        return Err(msg.m_type);
58	    }
59	
60	    let endpoint = i32::from_ne_bytes(
61	        msg.payload[0..4]
62	            .try_into()
63	            .expect("payload is at least 4 bytes"),
64	    );
65	    let mut name = [0u8; SYS_GETINFO_NAME_LEN];
66	    name.copy_from_slice(&msg.payload[12..12 + SYS_GETINFO_NAME_LEN]);
67	
68	    let sef = Sef {
69	        endpoint,
70	        name,
71	        signal_handler: cfg.signal_handler,
72	    };
73	
74	    // First words from EL0: announce on the kernel debug channel (slice 5.1).
75	    // Placed after GET_WHOAMI but *before* `init_fresh` (which publishes to DS)
76	    // so the line proves `SYS_DIAGCTL` on its own, independent of DS being up.
77	    // The kernel supplies the `[diag <name>]` prefix from its own proc slot, so
78	    // one constant string identifies every server distinctly. Best-effort: a
79	    // failed debug print must not abort a server's startup.
80	    let _ = diag_print("sef ready");
81	
82	    if let Some(init) = cfg.init_fresh {
83	        let rc = init(endpoint, &name);
84	        if rc != OK {
85	            return Err(rc);
86	        }
87	    }
88	
89	    Ok(sef)
90	}
91	
92	impl Sef {
93	    /// This server's own endpoint, as learned at startup.
94	    pub fn endpoint(&self) -> Endpoint {
95	        self.endpoint
96	    }
97	
98	    /// This server's name (NUL-padded), as learned at startup.
99	    pub fn name(&self) -> &[u8; SYS_GETINFO_NAME_LEN] {
100	        &self.name
101	    }
102	
103	    /// Receive the next *application* message into `msg`, transparently handling
104	    /// any SEF control messages that arrive first. Returns `OK` (0) once an
105	    /// application message is in `msg`, or a negative error code if the
106	    /// underlying receive failed (the server typically just loops and retries,
107	    /// matching the old hand-rolled `if ipc_receive(..) != 0 { continue }`).
108	    pub fn receive(&self, msg: &mut Message) -> i32 {
109	        loop {
110	            let rc = ipc_receive(ANY, msg);
111	            if rc != OK {
112	                return rc;
113	            }
114	            match classify(msg) {
115	                SefEvent::Application => return OK,
116	                SefEvent::Ping => {
117	                    // Acknowledge the RS heartbeat. A deferred notify still
118	                    // returns OK; any error just means RS re-pings later, so we
119	                    // ignore the result and wait for the next message.
120	                    //
121	                    // TODO(phase 4, RS heartbeat): this ack needs the server's
122	                    // own `ipc_to` bit for RS to be open (cf. `install_stub_d_priv`
123	                    // opening VM→D). Until RS actually pings, that reverse edge is
124	                    // unwired, so the ack would return `ECALLDENIED` — harmless
125	                    // while the heartbeat is dormant, but the wiring must land
126	                    // with the heartbeat or RS will conclude the server is dead.
127	                    let _ = ipc_notify(boot_endpoint(RS_PROC_NR));
128	                }
129	                SefEvent::Signal(signo) => {
130	                    if let Some(handler) = self.signal_handler {
131	                        handler(signo);
132	                    }
133	                }
134	                SefEvent::Init => {
135	                    // Fresh init already ran in sef_startup; the minimal
136	                    // Phase-4 SEF has nothing to do for a re-init request.
137	                    //
138	                    // TODO(phase 4, RS-driven re-init): nail down the reply
139	                    // contract before RS sends this. If RS issues SEF_INIT as a
140	                    // SENDREC it blocks until the server replies — this arm would
141	                    // then have to send an ack or RS hangs. Nothing sends SEF_INIT
142	                    // yet, so swallowing it is correct for now. The same caveat
143	                    // applies to a SENDREC-delivered SEF_SIGNAL.
144	                }
145	            }
146	        }
147	    }
148	}
