122	const fn tty_rule_pattern() -> [u8; TTY_RULE_LEN] {
123	    let mut b = [b'-'; TTY_RULE_LEN];
124	    let prefix = b"minix.rs vfs: short-write rule ";
125	    let mut i = 0;
126	    while i < prefix.len() {
127	        b[i] = prefix[i];
128	        i += 1;
129	    }
130	    // Ends the line at the clamp boundary.
131	    b[CDEV_MAX_IO - 1] = b'\n';
132	    // Past the clamp: must never reach the console.
133	    let tail = b"TRUNCATE";
134	    let mut j = 0;
135	    while j < tail.len() {
136	        b[CDEV_MAX_IO + j] = tail[j];
137	        j += 1;
138	    }
139	    b
140	}
