207	/// Serve one `VFS_WRITE`. Returns the reply `m_type`: bytes written (`>= 0`), or
208	/// a negative errno.
209	///
210	/// The checks, in order — each is the first thing that can be wrong given the
211	/// ones before it:
212	///
213	/// 1. The descriptor resolves, through the caller's own row of the fd table. The
214	///    caller is named by the kernel-stamped `m_source`, so a client cannot ask
215	///    about another process's descriptors.
216	/// 2. `len < 0` → `EINVAL`. Left unchecked it would widen into a ~16 EiB `u64`
217	///    byte count for the grant.
218	/// 3. `len == 0` → `0`, a legal empty write. Deliberately *before* the grant, so
219	///    a client polling with `len = 0` gets no grant issued at all and cannot use
220	///    it to probe the granting path. TTY applies the same rule one layer down.
221	/// 4. The buffer lies in the user address range. This is `user_range_ok`, the
222	///    no-alignment variant grants use — a `write()` buffer is a byte buffer.
223	///    Defence in depth rather than the load-bearing gate: the kernel's copy
224	///    engine walks the caller's page tables and answers `EFAULT` for anything
225	///    unmapped regardless (D5), which is what makes a bad pointer an errno here
226	///    instead of a fault in the caller.
227	///
228	/// Then the grant. `caller_e` is the **kernel-stamped `m_source`** — the one fact
229	/// in this whole request a client cannot forge. VFS holds `SYS_PROC`, which is
230	/// what makes a magic grant legal for it; taking the owner from the payload
231	/// instead would let any VFS client aim TTY's privileged `SYS_SAFECOPY` at a
232	/// third party's address space through VFS. There is no payload field for it, and
233	/// there must never be one.
234	#[cfg_attr(test, allow(dead_code))]
235	fn do_write(
236	    caller_e: Endpoint,
237	    msg: &Message,
238	    grants: &mut GrantPool<GRANT_SLOTS>,
239	    tty: Endpoint,
240	) -> i32 {
241	    let req = write::parse(msg);
242	
243	    let minor = match fd::resolve(endpoint_proc(caller_e).get(), req.fd) {
244	        Ok(Fd::CharDev { minor }) => minor,
245	        // `resolve` maps a closed descriptor to `EBADF` itself, so this arm is
246	        // unreachable today. It exists so slice 5.8's regular-file variant shows
247	        // up as a compile error to be routed, not a silent fallthrough.
248	        Ok(Fd::Unused) => return EBADF,
249	        Err(e) => return e,
250	    };
251	
252	    let len = match write::validate(req.len, req.buf) {
253	        Ok(len) => len,
254	        Err(e) => return e,
255	    };
256	    if len == 0 {
257	        // A legal empty write. No grant is issued, so a client polling with
258	        // `len = 0` cannot use it to probe the granting path.
259	        return 0;
260	    }
261	
262	    // The single-copy hop: the grant names the *caller's* memory, so the kernel
263	    // moves the bytes from the caller straight into the driver.
264	    let gid = match grants.grant_magic(tty, caller_e, req.buf, len as u64, CPF_READ) {
265	        Ok(gid) => gid,
266	        // Verbatim: `ENOMEM` (VFS is out of grant slots) and a `SYS_SETGRANT`
267	        // failure are different problems, and neither is the client's fault.
268	        Err(e) => return e,
269	    };
270	    let written = write_all(tty, minor, gid, len);
271	    let _ = grants.revoke(gid);
272	    written
273	}
