284	/// one request always goes out and `len - off` is never zero.
285	#[cfg_attr(test, allow(dead_code))]
286	fn write_all(tty: Endpoint, minor: i32, gid: i32, len: usize) -> i32 {
287	    let mut off = 0usize;
288	    loop {
289	        let n = cdev_write(tty, minor, gid, (len - off) as i32, off as u64);
290	        match write::advance(off, len, n) {
291	            write::Step::More(next) => off = next,
292	            write::Step::Done(rc) => return rc,
293	        }
