//! The MinixFS v3 inode: its on-disk layout and codec.
//!
//! Layout is MINIX 3's `struct d2_inode` (`servers/mfs/inode.h`) — 64 bytes, of
//! which the last 40 are the ten zone pointers. Seven are direct, the eighth is
//! the single-indirect block, the ninth double-indirect, and the tenth is
//! reserved (MINIX never uses a triple-indirect on V2/V3).
//!
//! Inode *numbering* starts at 1: inode 0 does not exist, which is what makes 0 a
//! usable "no such entry" marker in a directory slot. [`ROOT_INODE`] is 1.

/// Bytes per on-disk inode. Divides the block size evenly (64 inodes per block).
pub const INODE_SIZE: usize = 64;

/// Zone pointers stored directly in the inode (`V2_NR_DZONES`).
pub const NR_DIRECT_ZONES: usize = 7;

/// Total zone pointers in an inode (`V2_NR_TZONES`): 7 direct, 1 single-indirect,
/// 1 double-indirect, 1 reserved.
pub const NR_TZONES: usize = 10;

/// Index of the single-indirect zone pointer within `Inode::zone`.
pub const SINGLE_INDIRECT_SLOT: usize = NR_DIRECT_ZONES;

/// Index of the double-indirect zone pointer. Never followed by [`crate::read`] —
/// see that module's `zone_for_offset` for why the single-indirect span already
/// covers every file this filesystem can hold.
pub const DOUBLE_INDIRECT_SLOT: usize = NR_DIRECT_ZONES + 1;

/// The root directory's inode number. Inode 0 does not exist.
pub const ROOT_INODE: u32 = 1;

/// `i_mode` type field mask (MINIX `I_TYPE`).
pub const I_TYPE: u16 = 0o170000;
/// `i_mode` type: regular file.
pub const I_REGULAR: u16 = 0o100000;
/// `i_mode` type: directory.
pub const I_DIRECTORY: u16 = 0o040000;

// Field offsets within the on-disk inode, in declaration order.
/// `d2_mode` (u16).
pub const INODE_MODE_OFF: usize = 0;
/// `d2_nlinks` (u16).
pub const INODE_NLINKS_OFF: usize = 2;
/// `d2_uid` (i16).
pub const INODE_UID_OFF: usize = 4;
/// `d2_gid` (u16).
pub const INODE_GID_OFF: usize = 6;
/// `d2_size` (i32).
pub const INODE_SIZE_OFF: usize = 8;
/// `d2_atime` (i32).
pub const INODE_ATIME_OFF: usize = 12;
/// `d2_mtime` (i32).
pub const INODE_MTIME_OFF: usize = 16;
/// `d2_ctime` (i32).
pub const INODE_CTIME_OFF: usize = 20;
/// `d2_zone[0]` (u32 × [`NR_TZONES`]).
pub const INODE_ZONE_OFF: usize = 24;

// The zone array is what fills the inode out to exactly 64 bytes.
const _: () = assert!(INODE_ZONE_OFF + NR_TZONES * 4 == INODE_SIZE);
const _: () = assert!(NR_DIRECT_ZONES < NR_TZONES);
const _: () = assert!(crate::MFS_BLOCK_SIZE.is_multiple_of(INODE_SIZE));

/// An on-disk inode, decoded.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Inode {
    pub mode: u16,
    pub nlinks: u16,
    pub uid: i16,
    pub gid: u16,
    /// File size in bytes. Signed on disk (MINIX's `i32_t`); a negative value is
    /// a corrupt inode, and [`crate::read::zone_for_offset`] never consults it.
    pub size: i32,
    pub atime: i32,
    pub mtime: i32,
    pub ctime: i32,
    /// Zone pointers. `0` is a hole — zone 0 is not a data zone in MinixFS.
    pub zone: [u32; NR_TZONES],
}

impl Inode {
    /// An all-zero inode: mode 0, no links, no zones. What a freshly formatted
    /// inode table is full of.
    pub const EMPTY: Self = Self {
        mode: 0,
        nlinks: 0,
        uid: 0,
        gid: 0,
        size: 0,
        atime: 0,
        mtime: 0,
        ctime: 0,
        zone: [0; NR_TZONES],
    };

    /// Decode an inode from the first [`INODE_SIZE`] bytes of `b`. `None` if `b`
    /// is short.
    pub fn from_le_bytes(b: &[u8]) -> Option<Self> {
        if b.len() < INODE_SIZE {
            return None;
        }
        let mut zone = [0u32; NR_TZONES];
        for (i, z) in zone.iter_mut().enumerate() {
            *z = rd_u32(b, INODE_ZONE_OFF + i * 4);
        }
        Some(Self {
            mode: rd_u16(b, INODE_MODE_OFF),
            nlinks: rd_u16(b, INODE_NLINKS_OFF),
            uid: rd_u16(b, INODE_UID_OFF) as i16,
            gid: rd_u16(b, INODE_GID_OFF),
            size: rd_u32(b, INODE_SIZE_OFF) as i32,
            atime: rd_u32(b, INODE_ATIME_OFF) as i32,
            mtime: rd_u32(b, INODE_MTIME_OFF) as i32,
            ctime: rd_u32(b, INODE_CTIME_OFF) as i32,
            zone,
        })
    }

    /// Encode back to the on-disk form.
    pub fn to_le_bytes(&self) -> [u8; INODE_SIZE] {
        let mut b = [0u8; INODE_SIZE];
        wr_u16(&mut b, INODE_MODE_OFF, self.mode);
        wr_u16(&mut b, INODE_NLINKS_OFF, self.nlinks);
        wr_u16(&mut b, INODE_UID_OFF, self.uid as u16);
        wr_u16(&mut b, INODE_GID_OFF, self.gid);
        wr_u32(&mut b, INODE_SIZE_OFF, self.size as u32);
        wr_u32(&mut b, INODE_ATIME_OFF, self.atime as u32);
        wr_u32(&mut b, INODE_MTIME_OFF, self.mtime as u32);
        wr_u32(&mut b, INODE_CTIME_OFF, self.ctime as u32);
        for (i, z) in self.zone.iter().enumerate() {
            wr_u32(&mut b, INODE_ZONE_OFF + i * 4, *z);
        }
        b
    }

    /// Is this a directory?
    pub fn is_dir(&self) -> bool {
        self.mode & I_TYPE == I_DIRECTORY
    }

    /// Is this a regular file?
    pub fn is_reg(&self) -> bool {
        self.mode & I_TYPE == I_REGULAR
    }
}

fn rd_u16(b: &[u8], off: usize) -> u16 {
    u16::from_le_bytes([b[off], b[off + 1]])
}

fn rd_u32(b: &[u8], off: usize) -> u32 {
    u32::from_le_bytes([b[off], b[off + 1], b[off + 2], b[off + 3]])
}

fn wr_u16(b: &mut [u8], off: usize, v: u16) {
    b[off..off + 2].copy_from_slice(&v.to_le_bytes());
}

fn wr_u32(b: &mut [u8], off: usize, v: u32) {
    b[off..off + 4].copy_from_slice(&v.to_le_bytes());
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Inode {
        let mut zone = [0u32; NR_TZONES];
        // Distinct, non-sequential values so a swapped pair of slots fails.
        for (i, z) in zone.iter_mut().enumerate() {
            *z = 100 + (i as u32) * 7;
        }
        Inode {
            mode: I_REGULAR | 0o644,
            nlinks: 1,
            uid: -3,
            gid: 42,
            size: 123_456,
            atime: 11,
            mtime: 22,
            ctime: 33,
            zone,
        }
    }

    #[test]
    fn the_codec_round_trips_every_field() {
        let i = sample();
        assert_eq!(Inode::from_le_bytes(&i.to_le_bytes()), Some(i));
    }

    #[test]
    fn a_short_buffer_decodes_to_none() {
        let bytes = sample().to_le_bytes();
        for short in [0usize, 1, 24, INODE_SIZE - 1] {
            assert_eq!(Inode::from_le_bytes(&bytes[..short]), None, "{short}");
        }
    }

    #[test]
    fn the_encoded_form_is_exactly_sixty_four_bytes() {
        assert_eq!(sample().to_le_bytes().len(), INODE_SIZE);
        assert_eq!(INODE_SIZE, 64);
        assert_eq!(crate::MFS_BLOCK_SIZE / INODE_SIZE, 64);
    }

    #[test]
    fn the_zone_array_starts_where_the_timestamps_end() {
        // The zone pointers are what a reader actually follows, so pin their
        // offset against the fields that precede them rather than a literal.
        assert_eq!(INODE_CTIME_OFF + 4, INODE_ZONE_OFF);
        assert_eq!(INODE_ZONE_OFF, 24);
        assert_eq!(SINGLE_INDIRECT_SLOT, 7);
        assert_eq!(DOUBLE_INDIRECT_SLOT, 8);
    }

    #[test]
    fn a_zone_pointer_lands_at_its_own_offset() {
        // Encode one non-zero pointer at a time and check nothing else moved.
        for slot in 0..NR_TZONES {
            let mut i = Inode::EMPTY;
            i.zone[slot] = 0xDEAD_BEEF;
            let b = i.to_le_bytes();
            assert_eq!(
                &b[INODE_ZONE_OFF + slot * 4..INODE_ZONE_OFF + slot * 4 + 4],
                &0xDEAD_BEEFu32.to_le_bytes(),
                "slot {slot}"
            );
            assert_eq!(Inode::from_le_bytes(&b).unwrap().zone[slot], 0xDEAD_BEEF);
        }
    }

    #[test]
    fn the_type_bits_classify_regular_files_and_directories() {
        let mut i = Inode::EMPTY;
        i.mode = I_REGULAR | 0o755;
        assert!(i.is_reg());
        assert!(!i.is_dir());

        i.mode = I_DIRECTORY | 0o755;
        assert!(i.is_dir());
        assert!(!i.is_reg());

        // Permission bits alone are neither: an all-zero inode is a free slot.
        assert!(!Inode::EMPTY.is_dir());
        assert!(!Inode::EMPTY.is_reg());
    }

    #[test]
    fn an_empty_inode_encodes_to_all_zeroes() {
        assert_eq!(Inode::EMPTY.to_le_bytes(), [0u8; INODE_SIZE]);
        assert_eq!(Inode::from_le_bytes(&[0u8; INODE_SIZE]), Some(Inode::EMPTY));
    }
}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! MinixFS v3 directory entries.
//!
//! Layout is MINIX 3's `struct direct` (`include/minix/dir.h`) at V3's sizing: a
//! 4-byte inode number followed by a 60-byte name field, 64 bytes total, so a
//! 4096-byte block holds exactly 64 entries.
//!
//! The name is **NUL-padded, not NUL-terminated**: a name of exactly
//! [`NAME_MAX`] bytes fills the field with no room for a terminator. That is why
//! [`DirEntry::name_str`] trims at the first NUL rather than looking for one.
//!
//! Inode number `0` marks a free slot. Directories are not compacted — a removed
//! entry leaves a zeroed slot behind — so a reader must skip them, which is what
//! [`iter_block`] does.

/// Bytes per on-disk directory entry.
pub const DIRENT_SIZE: usize = 64;

/// Longest file name, in bytes (`MFS_DIRSIZ` for V3).
pub const NAME_MAX: usize = 60;

/// Offset of the inode number within an entry (u32).
pub const DIRENT_INO_OFF: usize = 0;
/// Offset of the name field within an entry ([`NAME_MAX`] bytes, NUL-padded).
pub const DIRENT_NAME_OFF: usize = 4;

const _: () = assert!(DIRENT_NAME_OFF + NAME_MAX == DIRENT_SIZE);
const _: () = assert!(crate::MFS_BLOCK_SIZE.is_multiple_of(DIRENT_SIZE));

/// One directory entry, decoded.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct DirEntry {
    /// Inode number. `0` marks a free slot.
    pub ino: u32,
    /// The name field verbatim, NUL-padded.
    pub name: [u8; NAME_MAX],
}

impl DirEntry {
    /// A free slot.
    pub const EMPTY: Self = Self {
        ino: 0,
        name: [0; NAME_MAX],
    };

    /// Build an entry from an inode number and a name. `None` if the name is
    /// empty, longer than [`NAME_MAX`], or contains a NUL or `/`.
    ///
    /// Rejecting the separator here is what keeps a path component from being
    /// able to *contain* a path: `mkfs-mfs` splits on `/` before it gets here, and
    /// a name that smuggled one back in would resolve differently depending on
    /// which side of the split looked at it.
    pub fn new(ino: u32, name: &[u8]) -> Option<Self> {
        if name.is_empty() || name.len() > NAME_MAX {
            return None;
        }
        if name.contains(&0) || name.contains(&b'/') {
            return None;
        }
        let mut e = Self::EMPTY;
        e.ino = ino;
        e.name[..name.len()].copy_from_slice(name);
        Some(e)
    }

    /// Decode an entry from the first [`DIRENT_SIZE`] bytes of `b`. `None` if `b`
    /// is short.
    pub fn from_le_bytes(b: &[u8]) -> Option<Self> {
        if b.len() < DIRENT_SIZE {
            return None;
        }
        let ino = u32::from_le_bytes([b[0], b[1], b[2], b[3]]);
        let mut name = [0u8; NAME_MAX];
        name.copy_from_slice(&b[DIRENT_NAME_OFF..DIRENT_NAME_OFF + NAME_MAX]);
        Some(Self { ino, name })
    }

    /// Encode back to the on-disk form.
    pub fn to_le_bytes(&self) -> [u8; DIRENT_SIZE] {
        let mut b = [0u8; DIRENT_SIZE];
        b[DIRENT_INO_OFF..DIRENT_INO_OFF + 4].copy_from_slice(&self.ino.to_le_bytes());
        b[DIRENT_NAME_OFF..DIRENT_NAME_OFF + NAME_MAX].copy_from_slice(&self.name);
        b
    }

    /// The name as text, trimmed at the first NUL.
    ///
    /// Empty for a name that is not valid UTF-8 — the `BootImage::record`
    /// precedent. A caller comparing against a known name therefore gets a
    /// mismatch rather than a panic, and a free slot (all-zero name) is empty too,
    /// which is consistent: neither names anything.
    pub fn name_str(&self) -> &str {
        let end = self
            .name
            .iter()
            .position(|&b| b == 0)
            .unwrap_or(self.name.len());
        core::str::from_utf8(&self.name[..end]).unwrap_or("")
    }
}

/// Iterate the **live** entries of one directory block, skipping free slots.
///
/// A trailing partial entry (a block whose length is not a multiple of
/// [`DIRENT_SIZE`]) is ignored rather than half-decoded, so a short read cannot
/// synthesize an entry out of whatever followed it.
pub fn iter_block(block: &[u8]) -> impl Iterator<Item = DirEntry> + '_ {
    block
        .chunks_exact(DIRENT_SIZE)
        .filter_map(DirEntry::from_le_bytes)
        .filter(|e| e.ino != 0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_codec_round_trips() {
        let e = DirEntry::new(7, b"hello").unwrap();
        assert_eq!(DirEntry::from_le_bytes(&e.to_le_bytes()), Some(e));
        assert_eq!(e.name_str(), "hello");
        assert_eq!(e.ino, 7);
    }

    #[test]
    fn an_entry_is_sixty_four_bytes_and_a_block_holds_sixty_four() {
        assert_eq!(DIRENT_SIZE, 64);
        assert_eq!(NAME_MAX, 60);
        assert_eq!(crate::MFS_BLOCK_SIZE / DIRENT_SIZE, 64);
    }

    #[test]
    fn a_maximum_length_name_round_trips_without_a_terminator() {
        // The whole point of NUL-*padding*: at exactly NAME_MAX there is no room
        // for a terminator, so a reader that looked for one would truncate.
        let name = [b'x'; NAME_MAX];
        let e = DirEntry::new(3, &name).unwrap();
        let back = DirEntry::from_le_bytes(&e.to_le_bytes()).unwrap();
        assert_eq!(back.name_str().len(), NAME_MAX);
        assert_eq!(back.name, name);
    }

    #[test]
    fn a_name_one_byte_too_long_is_refused() {
        assert_eq!(DirEntry::new(3, &[b'x'; NAME_MAX + 1]), None);
    }

    #[test]
    fn an_empty_name_is_refused() {
        assert_eq!(DirEntry::new(3, b""), None);
    }

    #[test]
    fn a_name_containing_a_separator_or_nul_is_refused() {
        assert_eq!(DirEntry::new(3, b"bin/hello"), None);
        assert_eq!(DirEntry::new(3, b"he\0llo"), None);
    }

    #[test]
    fn a_short_buffer_decodes_to_none() {
        let e = DirEntry::new(1, b".").unwrap();
        let b = e.to_le_bytes();
        assert_eq!(DirEntry::from_le_bytes(&b[..DIRENT_SIZE - 1]), None);
    }

    #[test]
    fn iter_block_skips_free_slots_and_trailing_partials() {
        let mut block = [0u8; DIRENT_SIZE * 4 + 7];
        for (i, (ino, name)) in [(1u32, &b"."[..]), (0, b"ghost"), (2, b".."), (9, b"bin")]
            .into_iter()
            .enumerate()
        {
            let e = DirEntry::new(ino, name).unwrap();
            block[i * DIRENT_SIZE..(i + 1) * DIRENT_SIZE].copy_from_slice(&e.to_le_bytes());
        }
        // Slot 1 was written with ino 0, so it is free regardless of its name.
        let names: heapless::Names = iter_block(&block).map(|e| e.ino).collect();
        assert_eq!(names.as_slice(), &[1, 2, 9]);
        // ...and the 7 trailing bytes never became a fifth entry.
        assert_eq!(iter_block(&block).count(), 3);
    }

    /// A tiny fixed-capacity collector so the iterator test needs no allocator.
    mod heapless {
        #[derive(Default)]
        pub struct Names {
            buf: [u32; 8],
            len: usize,
        }
        impl Names {
            pub fn as_slice(&self) -> &[u32] {
                &self.buf[..self.len]
            }
        }
        impl FromIterator<u32> for Names {
            fn from_iter<I: IntoIterator<Item = u32>>(it: I) -> Self {
                let mut n = Self::default();
                for v in it {
                    n.buf[n.len] = v;
                    n.len += 1;
                }
                n
            }
        }
    }
}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! Where everything sits on the device — the arithmetic `mkfs-mfs` and every
//! reader must agree on or nothing works.
//!
//! A MinixFS v3 device is laid out as:
//!
//! ```text
//!   block 0        boot block (bytes 0..1024) + superblock (bytes 1024..1055)
//!   block 1        reserved
//!   block 2..      inode bitmap, zone bitmap, inode table, then data zones
//! ```
//!
//! There is no I/O here and no floating-point: it is pure integer arithmetic over
//! `(ninodes, zones, block_size)`, which is exactly why it carries the crate's
//! densest unit tests. A one-block error anywhere in this file makes every inode
//! read return garbage from the middle of a bitmap.
//!
//! ## The two places minix.rs makes its own choice
//!
//! **[`START_BLOCK`] is 2.** MinixFS puts the superblock at byte 1024, so with
//! 1 KiB blocks the boot block and the superblock really are blocks 0 and 1 and
//! the bitmaps start at 2. With 4 KiB blocks both live inside block 0 and block 1
//! is spare — minix.rs keeps the bitmaps at 2 anyway rather than reclaiming it,
//! because `START_BLOCK = 2` is what MINIX's own `const.h` says and one spare
//! block out of 256 is not worth a divergence a reader could get wrong.
//!
//! **The zone bitmap is sized over *all* zones, not just the data zones.** The
//! exact size depends on `first_data_zone`, which depends on the bitmap size — a
//! circular definition MINIX's `mkfs.mfs` breaks by over-estimating in exactly
//! this way. Over-estimating keeps [`layout`] a pure non-iterative function, and
//! costs nothing: at 4 KiB blocks one bitmap block covers 32768 zones, which is
//! 128× the whole slice-5.7 image.

use crate::inode::INODE_SIZE;

/// First block of the filesystem proper — the inode bitmap. See the module docs
/// for why it is 2 rather than 1 at a 4 KiB block size.
pub const START_BLOCK: u32 = 2;

/// Blocks needed to hold `bits` bitmap bits at `block_size` bytes per block.
///
/// `0` bits needs `0` blocks; every real caller passes at least 1, because bit 0
/// of both bitmaps is reserved (neither inode 0 nor zone 0 exists).
pub fn bitmap_blocks(bits: usize, block_size: usize) -> u32 {
    let per_block = block_size * 8;
    bits.div_ceil(per_block) as u32
}

/// Where each region of the device starts, and how long it is. All values are
/// block numbers / block counts.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Layout {
    /// First block of the inode bitmap.
    pub imap_start: u32,
    /// Blocks of inode bitmap.
    pub imap_blocks: u32,
    /// First block of the zone bitmap.
    pub zmap_start: u32,
    /// Blocks of zone bitmap.
    pub zmap_blocks: u32,
    /// First block of the inode table.
    pub inode_start: u32,
    /// Blocks of inode table.
    pub inode_blocks: u32,
    /// First zone available for file data. With `log_zone_size == 0` a zone *is*
    /// a block, so this is also the first data block.
    pub first_data_zone: u32,
}

/// Compute the layout of a device with `ninodes` inodes and `zones` total zones.
///
/// `block_size` must be non-zero and a multiple of [`INODE_SIZE`]; every caller in
/// this workspace passes [`crate::MFS_BLOCK_SIZE`].
pub fn layout(ninodes: u32, zones: u32, block_size: usize) -> Layout {
    let inodes_per_block = block_size / INODE_SIZE;

    // Bit 0 of each bitmap is reserved (there is no inode 0 and no zone 0), hence
    // the `1 +`. The zone bitmap is deliberately sized over every zone — see the
    // module docs.
    let imap_blocks = bitmap_blocks(1 + ninodes as usize, block_size);
    let zmap_blocks = bitmap_blocks(1 + zones as usize, block_size);
    let inode_blocks = (ninodes as usize).div_ceil(inodes_per_block) as u32;

    let imap_start = START_BLOCK;
    let zmap_start = imap_start + imap_blocks;
    let inode_start = zmap_start + zmap_blocks;
    let first_data_zone = inode_start + inode_blocks;

    Layout {
        imap_start,
        imap_blocks,
        zmap_start,
        zmap_blocks,
        inode_start,
        inode_blocks,
        first_data_zone,
    }
}

/// Bit index in the **inode** bitmap for inode number `ino`.
///
/// The identity map: bit 0 is reserved because inode 0 does not exist, so inode
/// `n` is bit `n`.
pub fn imap_bit(ino: u32) -> u32 {
    ino
}

/// Bit index in the **zone** bitmap for zone number `zone`.
///
/// MINIX's convention (`alloc_zone`/`free_zone` in `servers/mfs/alloc.c`): the
/// bitmap is based at `first_data_zone - 1`, so bit 0 corresponds to a zone that
/// is *not* a data zone and is always marked in use. `None` for a zone below that
/// base — such a zone is metadata and has no bitmap bit at all.
pub fn zmap_bit(zone: u32, first_data_zone: u32) -> Option<u32> {
    zone.checked_sub(first_data_zone - 1)
}

#[cfg(test)]
mod tests {
    use super::*;

    const BS: usize = crate::MFS_BLOCK_SIZE;

    #[test]
    fn bitmap_blocks_rounds_up_at_every_boundary() {
        let per_block = BS * 8; // 32768 bits in a 4 KiB block
        assert_eq!(bitmap_blocks(0, BS), 0);
        assert_eq!(bitmap_blocks(1, BS), 1);
        assert_eq!(bitmap_blocks(per_block - 1, BS), 1);
        assert_eq!(bitmap_blocks(per_block, BS), 1);
        assert_eq!(bitmap_blocks(per_block + 1, BS), 2);
        assert_eq!(bitmap_blocks(2 * per_block, BS), 2);
        assert_eq!(bitmap_blocks(2 * per_block + 1, BS), 3);
    }

    #[test]
    fn bitmap_blocks_scales_with_the_block_size() {
        // A smaller block holds fewer bits, so the same bit count needs more
        // blocks. (1 KiB is not a size minix.rs formats, but the arithmetic must
        // not have 4096 baked in.)
        assert_eq!(bitmap_blocks(8192, 1024), 1);
        assert_eq!(bitmap_blocks(8193, 1024), 2);
        assert_eq!(bitmap_blocks(8193, 4096), 1);
    }

    /// The geometry of the slice-5.7 root image, computed by hand:
    ///
    /// * imap: `1 + 64 = 65` bits → 1 block, at 2
    /// * zmap: `1 + 256 = 257` bits → 1 block, at 3
    /// * inodes: `64 / (4096/64) = 1` block, at 4
    /// * first data zone: 5
    #[test]
    fn the_rootfs_geometry_matches_the_hand_computation() {
        assert_eq!(
            layout(64, 256, BS),
            Layout {
                imap_start: 2,
                imap_blocks: 1,
                zmap_start: 3,
                zmap_blocks: 1,
                inode_start: 4,
                inode_blocks: 1,
                first_data_zone: 5,
            }
        );
    }

    /// A second, larger geometry, also by hand: 4096 inodes needs
    /// `4096 / 64 = 64` inode-table blocks, and both bitmaps still fit in one.
    #[test]
    fn a_larger_geometry_matches_the_hand_computation() {
        assert_eq!(
            layout(4096, 65_536, BS),
            Layout {
                imap_start: 2,
                imap_blocks: 1,
                zmap_start: 3,
                zmap_blocks: 3, // 65537 bits / 32768 = 3 blocks
                inode_start: 6,
                inode_blocks: 64,
                first_data_zone: 70,
            }
        );
    }

    #[test]
    fn every_region_is_contiguous_and_ascending() {
        // Whatever the geometry, the four regions tile the device head to tail
        // with no gap: a gap would waste blocks, an overlap would corrupt.
        for (ninodes, zones) in [(1u32, 1u32), (64, 256), (1000, 5000), (4096, 65_536)] {
            let l = layout(ninodes, zones, BS);
            assert_eq!(l.imap_start, START_BLOCK, "{ninodes}/{zones}");
            assert_eq!(l.zmap_start, l.imap_start + l.imap_blocks);
            assert_eq!(l.inode_start, l.zmap_start + l.zmap_blocks);
            assert_eq!(l.first_data_zone, l.inode_start + l.inode_blocks);
        }
    }

    #[test]
    fn the_inode_table_is_sized_by_inodes_per_block() {
        let ipb = (BS / INODE_SIZE) as u32;
        assert_eq!(ipb, 64);
        assert_eq!(layout(1, 256, BS).inode_blocks, 1);
        assert_eq!(layout(ipb, 256, BS).inode_blocks, 1);
        assert_eq!(layout(ipb + 1, 256, BS).inode_blocks, 2);
        assert_eq!(layout(2 * ipb, 256, BS).inode_blocks, 2);
    }

    #[test]
    fn the_zone_bitmap_is_sized_over_every_zone_not_just_data_zones() {
        // The over-estimate the module docs describe: sizing over `1 + zones`
        // rather than `zones - first_data_zone + 1` is what keeps this function
        // non-iterative. It can only ever be too big, never too small.
        let l = layout(64, 256, BS);
        let data_zone_bits = (256 - l.first_data_zone + 1) as usize;
        assert_eq!(
            l.zmap_blocks.min(bitmap_blocks(data_zone_bits, BS)),
            bitmap_blocks(data_zone_bits, BS),
            "the zone bitmap must never be smaller than the data zones need"
        );
    }

    #[test]
    fn bit_zero_of_each_bitmap_is_reserved() {
        // Inode 0 and the zone just below the first data zone both map to bit 0,
        // which mkfs marks in use. That reservation is what lets 0 double as
        // "no such inode" / "hole" everywhere else in the format.
        assert_eq!(imap_bit(0), 0);
        assert_eq!(imap_bit(crate::inode::ROOT_INODE), 1);

        let fdz = layout(64, 256, BS).first_data_zone;
        assert_eq!(zmap_bit(fdz - 1, fdz), Some(0));
        assert_eq!(zmap_bit(fdz, fdz), Some(1));
        assert_eq!(zmap_bit(fdz + 10, fdz), Some(11));
    }

    #[test]
    fn a_metadata_zone_has_no_bitmap_bit() {
        // Anything below `first_data_zone - 1` is bitmap or inode table; asking
        // for its bit is a caller bug, and answering with a wrapped index would
        // silently mark an unrelated data zone.
        let fdz = layout(64, 256, BS).first_data_zone; // 5
        assert_eq!(zmap_bit(0, fdz), None);
        assert_eq!(zmap_bit(3, fdz), None);
        assert_eq!(zmap_bit(4, fdz), Some(0));
    }
}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! Locating an inode, and resolving a file offset to a zone.
//!
//! Every function here takes bytes the caller already fetched and returns *what
//! to fetch next*, never fetching anything itself. That is what lets slice 5.8's
//! MFS server drive the same code over `BDEV_READ` while `tools/mkfs-mfs` drives
//! it over a `Vec<u8>`, with no trait, no I/O abstraction, and no fake device in
//! the tests.
//!
//! ## Why `OutOfRange` is explicit
//!
//! [`zone_for_offset`] distinguishes a **hole** (a zone pointer that is legitimately
//! zero — the file is sparse there, and reading it yields zeroes) from an offset
//! **past the single-indirect span**, which is a caller bug. Collapsing the second
//! into "read zeroes" is how a filesystem silently returns wrong data; the D4
//! documented-`EINVAL` discipline says the caller hears about it.
//!
//! ## Why double-indirect is not implemented
//!
//! Seven direct zones plus one single-indirect block of `block_size / 4` pointers
//! is `7 + 1024` zones at a 4 KiB block size — **4.03 MiB**, which is larger than
//! any image this filesystem holds (the slice-5.7 root image is 1 MiB, and the VA
//! window reserved for it is 4 MiB). A double-indirect reader would therefore be
//! code no test could reach with a real image. [`ZoneLookup::OutOfRange`] is the
//! honest answer until an image needs one.

use crate::inode::{Inode, INODE_SIZE, NR_DIRECT_ZONES, SINGLE_INDIRECT_SLOT};
use crate::layout::Layout;

/// What backs a given file offset.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum ZoneLookup {
    /// The zone is named directly by the inode. Always non-zero.
    Direct(u32),
    /// The zone number lives at `slot` of the indirect block at zone `zone`.
    /// Fetch that block and pass it to [`zone_from_indirect`].
    Indirect { zone: u32, slot: usize },
    /// A hole: the relevant pointer is zero, so this range of the file has never
    /// been written and reads as zeroes.
    Hole,
    /// Past what the single-indirect span can address. See the module docs.
    OutOfRange,
}

/// Zone pointers one indirect block can hold.
pub fn ptrs_per_block(block_size: usize) -> usize {
    block_size / 4
}

/// Which block of the inode table holds inode `ino`, and its slot within it.
///
/// `None` for inode 0 (which does not exist) or an inode past the table. The
/// bound comes from `layout.inode_blocks`, so a caller cannot read an inode out of
/// the first data block by asking for one past the end.
pub fn inode_location(ino: u32, layout: &Layout, block_size: usize) -> Option<(u32, usize)> {
    if ino == 0 {
        return None;
    }
    let per_block = (block_size / INODE_SIZE) as u32;
    if per_block == 0 {
        return None;
    }
    let index = ino - 1;
    let block = layout.inode_start.checked_add(index / per_block)?;
    if block >= layout.inode_start.checked_add(layout.inode_blocks)? {
        return None;
    }
    Some((block, (index % per_block) as usize))
}

/// Decode the inode at `slot` of a fetched inode-table block.
///
/// `None` if the slot runs past the block — which is how a caller that mixed up
/// `block_size` finds out, rather than by reading the next inode's bytes.
pub fn inode_at(inode_block: &[u8], slot: usize) -> Option<Inode> {
    let start = slot.checked_mul(INODE_SIZE)?;
    let end = start.checked_add(INODE_SIZE)?;
    Inode::from_le_bytes(inode_block.get(start..end)?)
}

/// Resolve byte offset `off` within `inode` to the zone that backs it.
///
/// `off` is **not** checked against `inode.size`: that is the caller's policy
/// decision (a reader clamps to the size, `fsck` does not), and mixing it in here
/// would make a hole past EOF indistinguishable from a hole inside the file.
pub fn zone_for_offset(inode: &Inode, off: u64, block_size: usize) -> ZoneLookup {
    if block_size == 0 {
        return ZoneLookup::OutOfRange;
    }
    let index = off / block_size as u64;

    if index < NR_DIRECT_ZONES as u64 {
        let zone = inode.zone[index as usize];
        return if zone == 0 {
            ZoneLookup::Hole
        } else {
            ZoneLookup::Direct(zone)
        };
    }

    let slot = index - NR_DIRECT_ZONES as u64;
    if slot >= ptrs_per_block(block_size) as u64 {
        return ZoneLookup::OutOfRange;
    }
    let indirect = inode.zone[SINGLE_INDIRECT_SLOT];
    if indirect == 0 {
        // No indirect block at all: everything it would have covered is a hole.
        return ZoneLookup::Hole;
    }
    ZoneLookup::Indirect {
        zone: indirect,
        slot: slot as usize,
    }
}

/// Read zone pointer `slot` out of a fetched indirect block.
///
/// `None` if the slot runs past the block. `Some(0)` is a **hole**, not an error:
/// an indirect block's unused entries are zero, exactly like an inode's.
pub fn zone_from_indirect(block: &[u8], slot: usize) -> Option<u32> {
    let start = slot.checked_mul(4)?;
    let b = block.get(start..start.checked_add(4)?)?;
    Some(u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::inode::{I_REGULAR, NR_TZONES, ROOT_INODE};
    use crate::layout::layout;

    const BS: usize = crate::MFS_BLOCK_SIZE;

    #[test]
    fn ptrs_per_block_is_a_thousand_and_twenty_four_at_four_kib() {
        assert_eq!(ptrs_per_block(BS), 1024);
        assert_eq!(ptrs_per_block(1024), 256);
    }

    #[test]
    fn the_root_inode_is_the_first_slot_of_the_first_inode_block() {
        let l = layout(64, 256, BS);
        assert_eq!(inode_location(ROOT_INODE, &l, BS), Some((l.inode_start, 0)));
    }

    #[test]
    fn inodes_fill_a_block_then_move_to_the_next() {
        // 64 inodes per 4 KiB block. Inode 64 is the last slot of block 0 of the
        // table; inode 65 would be the first slot of block 1 — but this geometry
        // only has one inode block, so it is out of range instead.
        let l = layout(128, 256, BS); // two inode blocks
        assert_eq!(inode_location(64, &l, BS), Some((l.inode_start, 63)));
        assert_eq!(inode_location(65, &l, BS), Some((l.inode_start + 1, 0)));
        assert_eq!(inode_location(128, &l, BS), Some((l.inode_start + 1, 63)));
    }

    #[test]
    fn inode_zero_and_inodes_past_the_table_have_no_location() {
        let l = layout(64, 256, BS);
        assert_eq!(inode_location(0, &l, BS), None);
        // 64 inodes = exactly one block; 65 runs into the first data block, which
        // is precisely the read this bound exists to prevent.
        assert_eq!(inode_location(65, &l, BS), None);
        assert_eq!(inode_location(u32::MAX, &l, BS), None);
    }

    #[test]
    fn inode_at_decodes_the_named_slot_and_refuses_the_rest() {
        let mut block = [0u8; BS];
        let mut ino = Inode::EMPTY;
        ino.mode = I_REGULAR;
        ino.size = 99;
        ino.zone[0] = 12;
        block[63 * INODE_SIZE..64 * INODE_SIZE].copy_from_slice(&ino.to_le_bytes());

        assert_eq!(inode_at(&block, 63), Some(ino));
        assert_eq!(inode_at(&block, 0), Some(Inode::EMPTY));
        assert_eq!(inode_at(&block, 64), None, "past the end of the block");
        assert_eq!(inode_at(&block, usize::MAX), None, "no overflow panic");
    }

    /// An inode with every direct zone filled and a single-indirect block.
    fn spread() -> Inode {
        let mut i = Inode::EMPTY;
        i.mode = I_REGULAR;
        for slot in 0..NR_TZONES {
            i.zone[slot] = 200 + slot as u32;
        }
        i
    }

    #[test]
    fn the_first_seven_zones_come_straight_from_the_inode() {
        let i = spread();
        for idx in 0..NR_DIRECT_ZONES {
            let off = (idx * BS) as u64;
            assert_eq!(
                zone_for_offset(&i, off, BS),
                ZoneLookup::Direct(i.zone[idx]),
                "index {idx}"
            );
            // Any offset *within* the block resolves to the same zone.
            assert_eq!(
                zone_for_offset(&i, off + BS as u64 - 1, BS),
                ZoneLookup::Direct(i.zone[idx])
            );
        }
    }

    #[test]
    fn the_eighth_zone_onwards_goes_through_the_indirect_block() {
        let i = spread();
        // Index 7 is slot 0 of the indirect block — the boundary the whole
        // indirect arm hangs on.
        assert_eq!(
            zone_for_offset(&i, (NR_DIRECT_ZONES * BS) as u64, BS),
            ZoneLookup::Indirect {
                zone: i.zone[SINGLE_INDIRECT_SLOT],
                slot: 0
            }
        );
        assert_eq!(
            zone_for_offset(&i, ((NR_DIRECT_ZONES + 5) * BS) as u64, BS),
            ZoneLookup::Indirect {
                zone: i.zone[SINGLE_INDIRECT_SLOT],
                slot: 5
            }
        );
        // The last slot the single-indirect block can hold.
        let last = NR_DIRECT_ZONES + ptrs_per_block(BS) - 1;
        assert_eq!(
            zone_for_offset(&i, (last * BS) as u64, BS),
            ZoneLookup::Indirect {
                zone: i.zone[SINGLE_INDIRECT_SLOT],
                slot: ptrs_per_block(BS) - 1
            }
        );
    }

    #[test]
    fn one_zone_past_the_indirect_span_is_out_of_range_not_a_hole() {
        // The documented-EINVAL discipline: a filesystem that answered `Hole` here
        // would hand the caller zeroes for data it simply cannot address.
        let i = spread();
        let past = NR_DIRECT_ZONES + ptrs_per_block(BS);
        assert_eq!(
            zone_for_offset(&i, (past * BS) as u64, BS),
            ZoneLookup::OutOfRange
        );
        assert_eq!(zone_for_offset(&i, u64::MAX, BS), ZoneLookup::OutOfRange);
    }

    #[test]
    fn the_indirect_span_covers_more_than_four_mebibytes() {
        // The justification for not implementing double-indirect, as arithmetic
        // rather than prose: the largest addressable offset exceeds the 4 MiB VA
        // window reserved for the ramdisk, so no image can outgrow it.
        let addressable = (NR_DIRECT_ZONES + ptrs_per_block(BS)) as u64 * BS as u64;
        assert_eq!(addressable, 4_222_976);
        assert_eq!(addressable.max(4 * 1024 * 1024), addressable);
    }

    #[test]
    fn a_zero_pointer_is_a_hole_direct_or_indirect() {
        let mut i = Inode::EMPTY;
        i.mode = I_REGULAR;
        // No zones at all: every offset inside the direct range is a hole...
        assert_eq!(zone_for_offset(&i, 0, BS), ZoneLookup::Hole);
        // ...and so is everything the (absent) indirect block would have covered.
        assert_eq!(
            zone_for_offset(&i, (NR_DIRECT_ZONES * BS) as u64, BS),
            ZoneLookup::Hole
        );
        // A sparse file: zone 0 present, zone 1 missing, zone 2 present.
        i.zone[0] = 9;
        i.zone[2] = 11;
        assert_eq!(zone_for_offset(&i, 0, BS), ZoneLookup::Direct(9));
        assert_eq!(zone_for_offset(&i, BS as u64, BS), ZoneLookup::Hole);
        assert_eq!(
            zone_for_offset(&i, 2 * BS as u64, BS),
            ZoneLookup::Direct(11)
        );
    }

    #[test]
    fn zone_from_indirect_reads_the_named_slot() {
        let mut block = [0u8; BS];
        block[4..8].copy_from_slice(&77u32.to_le_bytes());
        block[(ptrs_per_block(BS) - 1) * 4..].copy_from_slice(&88u32.to_le_bytes());

        assert_eq!(zone_from_indirect(&block, 0), Some(0), "an unused slot");
        assert_eq!(zone_from_indirect(&block, 1), Some(77));
        assert_eq!(zone_from_indirect(&block, ptrs_per_block(BS) - 1), Some(88));
        assert_eq!(zone_from_indirect(&block, ptrs_per_block(BS)), None);
        assert_eq!(zone_from_indirect(&block, usize::MAX), None);
    }
}

