// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! `BDEV_READ` request parsing and validation — the driver's pure logic.
//!
//! Everything here is a total function over a [`Message`] or a scalar, so it
//! carries the crate's unit tests. The IPC round-trip and the kernel calls live in
//! `main.rs` and are verified through the boot log. Same split as
//! `drivers/tty`'s `cdev.rs` / `main.rs`.
//!
//! ## Three things this module is careful about
//!
//! **The granter is not here.** [`parse_read`] reads only the four payload
//! fields; the granter comes from the kernel-stamped `m_source`. A granter *field*
//! would make any grant-holding driver a confused deputy, aiming a privileged
//! cross-address-space copy wherever its client pointed. There is deliberately no
//! way to express one through this API — and no grant *offset* either, because
//! every client through slice 5.9 grants a buffer whose block starts at offset 0.
//!
//! **An over-long request is `EINVAL`, not a short read.** This is the deliberate
//! departure from `CDEV_WRITE`'s clamp. A short *write* is a POSIX contract every
//! client already loops over; a short *block read* is useless, because a
//! filesystem cannot interpret half a block, so clamping would push a retry loop
//! into every FS caller for nothing.
//!
//! **An out-of-range block is `EINVAL`, not `EIO`.** A block device's size is
//! known to its client (MFS reads it from the superblock's `s_zones`), so asking
//! past the end is a caller bug. `EIO` stays reserved for Phase 6's real media
//! errors, where the request was well-formed and the device failed.

use minixrs_kernel_shared::Message;
use minixrs_kernel_shared::callnr::{
    BDEV_BLOCK_SIZE, BDEV_GRANT_OFF, BDEV_LEN_OFF, BDEV_MAX_IO, BDEV_MINOR_OFF,
    BDEV_MINOR_RAMDISK, BDEV_BLOCK_OFF,
};
use minixrs_kernel_shared::error::{EINVAL, ENXIO};
use minixrs_kernel_shared::grant::grant_valid;
use minixrs_kernel_shared::uspace::RAMDISK_WINDOW_SIZE;
use minixrs_server_rt::{rd_i32, rd_u64};

/// A parsed `BDEV_READ` (or `BDEV_WRITE`) request. Field-for-field the payload,
/// with no interpretation applied — [`validate_read`] does that.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct ReadRequest {
    /// Device minor. Only [`BDEV_MINOR_RAMDISK`] exists today.
    pub minor: i32,
    /// Grant id naming the client's destination buffer. Must carry `CPF_WRITE`
    /// and name this driver as grantee — both checked by the kernel, not here.
    pub gid: i32,
    /// Bytes the client asked for. Must not exceed [`BDEV_MAX_IO`].
    pub len: i32,
    /// Block number within the device.
    pub block: u64,
}

/// Read a `BDEV_READ` request out of a message payload.
///
/// Total: every field is a fixed-offset scalar read that cannot fail
/// (`server-rt`'s accessors return `0` for an out-of-range offset), so a malformed
/// request becomes an invalid *value* that [`validate_read`] rejects, never a panic.
pub fn parse_read(msg: &Message) -> ReadRequest {
    ReadRequest {
        minor: rd_i32(msg, BDEV_MINOR_OFF),
        gid: rd_i32(msg, BDEV_GRANT_OFF),
        len: rd_i32(msg, BDEV_LEN_OFF),
        block: rd_u64(msg, BDEV_BLOCK_OFF),
    }
}

/// Decide which bytes of the device `req` names, or which errno to reply.
///
/// `Ok((byte_offset, len))` means "copy `len` bytes starting `byte_offset` into
/// the device, and reply `len`" — including `Ok((0, 0))`, a legal zero-length read
/// that needs no copy at all. `Err(e)` is a negative errno for the reply.
///
/// The checks, in the order a driver should apply them — each is the first thing
/// that can be wrong given the ones before it:
///
/// 1. `minor != BDEV_MINOR_RAMDISK` → `ENXIO`. The *device* does not exist;
///    nothing is wrong with the request.
/// 2. `len < 0` → `EINVAL`. A negative length would otherwise widen into a huge
///    `u64` byte count for the kernel copy.
/// 3. `len > BDEV_MAX_IO` → `EINVAL`. See the module docs.
/// 4. An invalid grant id → `EINVAL`. Cheap local reject of the one value that can
///    never name a grant; the kernel still re-validates index, sequence, access,
///    and grantee.
/// 5. `len == 0` → `Ok((0, 0))`, checked *after* the gid so a zero-length read
///    with a garbage grant is still reported as the error it is (TTY's rule).
/// 6. `block` at or past `device_blocks`, or a range that would run off the end →
///    `EINVAL`. `checked_mul`/`checked_add` throughout: servers ship `--release`
///    with `overflow-checks = false`, where `block * 4096` on a large block simply
///    *wraps* and would name a valid offset inside the device.
pub fn validate_read(req: ReadRequest, device_blocks: u64) -> Result<(u64, usize), i32> {
    if req.minor != BDEV_MINOR_RAMDISK {
        return Err(ENXIO);
    }
    if req.len < 0 {
        return Err(EINVAL);
    }
    if req.len as usize > BDEV_MAX_IO {
        return Err(EINVAL);
    }
    if !grant_valid(req.gid) {
        return Err(EINVAL);
    }
    let len = req.len as usize;
    if len == 0 {
        // Nothing is copied, so there is no offset to be out of range.
        return Ok((0, 0));
    }
    if req.block >= device_blocks {
        return Err(EINVAL);
    }
    let byte_off = req
        .block
        .checked_mul(BDEV_BLOCK_SIZE as u64)
        .ok_or(EINVAL)?;
    let end = byte_off.checked_add(len as u64).ok_or(EINVAL)?;
    let device_bytes = device_blocks
        .checked_mul(BDEV_BLOCK_SIZE as u64)
        .ok_or(EINVAL)?;
    if end > device_bytes {
        return Err(EINVAL);
    }
    Ok((byte_off, len))
}

/// Check the length the kernel reported for the ramdisk, and convert it to a block
/// count.
///
/// Cheap, host-testable, and it bounds the damage from a bogus reply: every later
/// range check is against the block count this returns, so a length the driver
/// accepted uncritically would become the ceiling on what it hands to
/// `SYS_SAFECOPY`.
///
/// `EINVAL` for zero, for a length that is not a whole number of blocks (the
/// driver serves whole blocks and nothing else), or for one larger than the VA
/// window the kernel reserves — which no honest reply can exceed, because the
/// kernel maps the image into that window.
pub fn validate_geometry(len: u64) -> Result<u64, i32> {
    if len == 0 {
        return Err(EINVAL);
    }
    if !len.is_multiple_of(BDEV_BLOCK_SIZE as u64) {
        return Err(EINVAL);
    }
    if len > RAMDISK_WINDOW_SIZE {
        return Err(EINVAL);
    }
    Ok(len / BDEV_BLOCK_SIZE as u64)
}

#[cfg(test)]
mod tests {
    use super::*;
    use minixrs_kernel_shared::grant::{GRANT_INVALID, grant_id};
    use minixrs_server_rt::{wr_i32, wr_u64};

    /// The slice-5.7 image: 256 blocks of 4 KiB.
    const BLOCKS: u64 = 256;
    const GOOD_GID: i32 = grant_id(3, 1);

    /// Build a well-formed `BDEV_READ` payload. The `granter` is deliberately not
    /// a parameter — there is no field for it — and neither is a grant offset.
    fn request(minor: i32, gid: i32, len: i32, block: u64) -> Message {
        let mut m = Message {
            m_source: 0,
            m_type: 0,
            payload: [0u8; 96],
        };
        wr_i32(&mut m, BDEV_MINOR_OFF, minor);
        wr_i32(&mut m, BDEV_GRANT_OFF, gid);
        wr_i32(&mut m, BDEV_LEN_OFF, len);
        wr_u64(&mut m, BDEV_BLOCK_OFF, block);
        m
    }

    #[test]
    fn parse_reads_every_field_from_its_own_offset() {
        // Four distinct values, so a swapped pair of offsets would fail.
        let m = request(0, GOOD_GID, 64, 17);
        assert_eq!(
            parse_read(&m),
            ReadRequest {
                minor: 0,
                gid: GOOD_GID,
                len: 64,
                block: 17,
            }
        );
    }

    #[test]
    fn parse_of_a_zeroed_payload_yields_a_rejectable_request() {
        // A client that sent nothing at all: minor 0 happens to be the ramdisk,
        // but grant id 0 has sequence 0 and index 0, and length 0 is a no-op. The
        // point is that nothing panics and nothing copies.
        let m = Message {
            m_source: 0,
            m_type: 0,
            payload: [0u8; 96],
        };
        let req = parse_read(&m);
        assert_eq!(req.len, 0);
        assert_eq!(validate_read(req, BLOCKS), Ok((0, 0)));
    }

    #[test]
    fn a_normal_read_resolves_to_its_byte_offset() {
        for block in [0u64, 1, 5, BLOCKS - 1] {
            let req = parse_read(&request(BDEV_MINOR_RAMDISK, GOOD_GID, 32, block));
            assert_eq!(
                validate_read(req, BLOCKS),
                Ok((block * BDEV_BLOCK_SIZE as u64, 32)),
                "block {block}"
            );
        }
    }

    #[test]
    fn a_whole_block_read_of_the_last_block_ends_exactly_at_the_device_end() {
        // The boundary the range check exists for: this is legal, and one byte
        // more would not be.
        let req = parse_read(&request(
            BDEV_MINOR_RAMDISK,
            GOOD_GID,
            BDEV_MAX_IO as i32,
            BLOCKS - 1,
        ));
        assert_eq!(
            validate_read(req, BLOCKS),
            Ok(((BLOCKS - 1) * BDEV_BLOCK_SIZE as u64, BDEV_MAX_IO))
        );
    }

    #[test]
    fn an_over_long_read_is_refused_not_clamped() {
        // The deliberate departure from CDEV. A driver that clamped here would
        // hand MFS half a block and report the truncation in a return value MFS
        // has no way to act on.
        for len in [BDEV_MAX_IO as i32 + 1, BDEV_MAX_IO as i32 * 2, i32::MAX] {
            let req = parse_read(&request(BDEV_MINOR_RAMDISK, GOOD_GID, len, 0));
            assert_eq!(validate_read(req, BLOCKS), Err(EINVAL), "len {len}");
        }
    }

    #[test]
    fn a_zero_length_read_is_ok_not_an_error() {
        let req = parse_read(&request(BDEV_MINOR_RAMDISK, GOOD_GID, 0, 0));
        assert_eq!(validate_read(req, BLOCKS), Ok((0, 0)));
    }

    #[test]
    fn an_unknown_minor_is_enxio() {
        for minor in [1i32, 7, -1, i32::MAX] {
            let req = parse_read(&request(minor, GOOD_GID, 32, 0));
            assert_eq!(validate_read(req, BLOCKS), Err(ENXIO), "minor {minor}");
        }
    }

    #[test]
    fn a_negative_length_is_einval() {
        // Left unchecked this would widen into a ~16 EiB `u64` byte count for the
        // kernel copy call.
        for len in [-1i32, -4096, i32::MIN] {
            let req = parse_read(&request(BDEV_MINOR_RAMDISK, GOOD_GID, len, 0));
            assert_eq!(validate_read(req, BLOCKS), Err(EINVAL), "len {len}");
        }
    }

    #[test]
    fn an_invalid_grant_id_is_einval() {
        for gid in [GRANT_INVALID, -2, i32::MIN] {
            let req = parse_read(&request(BDEV_MINOR_RAMDISK, gid, 32, 0));
            assert_eq!(validate_read(req, BLOCKS), Err(EINVAL), "gid {gid}");
        }
    }

    #[test]
    fn a_block_past_the_device_is_einval() {
        for block in [BLOCKS, BLOCKS + 1, u64::MAX] {
            let req = parse_read(&request(BDEV_MINOR_RAMDISK, GOOD_GID, 32, block));
            assert_eq!(validate_read(req, BLOCKS), Err(EINVAL), "block {block}");
        }
    }

    /// The reason every step uses `checked_*`. Servers ship `--release` with
    /// `overflow-checks = false`, so `block * 4096` on a huge block number wraps
    /// silently — and a wrapped product is a *valid-looking* offset inside the
    /// device, which is the worst possible outcome for a range check.
    #[test]
    fn a_block_number_that_would_overflow_its_byte_offset_is_refused() {
        // `u64::MAX / 4096 + 1` is the smallest block whose byte offset wraps.
        let wrapping = u64::MAX / BDEV_BLOCK_SIZE as u64 + 1;
        assert_eq!(wrapping.wrapping_mul(BDEV_BLOCK_SIZE as u64), 0);
        let req = parse_read(&request(BDEV_MINOR_RAMDISK, GOOD_GID, 32, wrapping));
        // Caught by the device-size check before the multiply is even reached,
        // which is itself the point: the cheap check comes first.
        assert_eq!(validate_read(req, BLOCKS), Err(EINVAL));
        // ...and it is still refused for a device large enough to reach it.
        assert_eq!(validate_read(req, u64::MAX), Err(EINVAL));
    }

    /// Check order matters: a request that is wrong in two ways must report the
    /// *first* problem, so a client fixing one error learns about the next.
    #[test]
    fn the_minor_check_precedes_every_other_check() {
        let req = parse_read(&request(9, GRANT_INVALID, -5, u64::MAX));
        assert_eq!(validate_read(req, BLOCKS), Err(ENXIO));

        // ...and a bad grant is reported even on a zero-length read, rather than
        // being masked by the `Ok((0, 0))` fast path.
        let req = parse_read(&request(BDEV_MINOR_RAMDISK, GRANT_INVALID, 0, 0));
        assert_eq!(validate_read(req, BLOCKS), Err(EINVAL));
    }

    #[test]
    fn a_plausible_geometry_converts_to_a_block_count() {
        assert_eq!(validate_geometry(1024 * 1024), Ok(256));
        assert_eq!(validate_geometry(BDEV_BLOCK_SIZE as u64), Ok(1));
        assert_eq!(
            validate_geometry(RAMDISK_WINDOW_SIZE),
            Ok(RAMDISK_WINDOW_SIZE / BDEV_BLOCK_SIZE as u64)
        );
    }

    #[test]
    fn an_implausible_geometry_is_refused() {
        assert_eq!(validate_geometry(0), Err(EINVAL), "an empty device");
        assert_eq!(validate_geometry(1), Err(EINVAL), "a partial block");
        assert_eq!(
            validate_geometry(BDEV_BLOCK_SIZE as u64 + 1),
            Err(EINVAL),
            "a trailing partial block"
        );
        assert_eq!(
            validate_geometry(RAMDISK_WINDOW_SIZE + BDEV_BLOCK_SIZE as u64),
            Err(EINVAL),
            "larger than the window the kernel maps it into"
        );
        assert_eq!(validate_geometry(u64::MAX), Err(EINVAL));
    }
}

// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
//! minix.rs `memory` driver — the boot ramdisk, read-only (slice 5.7, decision D3).
//!
//! The first *block* device in minix.rs, and the storage MFS lands on in slice 5.8.
//! `kernel/build.rs` builds a MinixFS v3 image at compile time and packs it into
//! the MXBI archive as a non-ELF blob; the kernel copies it into RAM frames and
//! maps them into this driver's address space at [`RAMDISK_VA`] while building it.
//! This driver asks where (`SYS_GETINFO(GET_RAMDISK)`, which only it may call) and
//! then serves [`BDEV_READ`].
//!
//! MINIX 3 boots the same shape, and Phase 6 swaps virtio-blk in underneath an
//! unchanged MFS — which is why nothing here knows what a filesystem is.
//!
//! ## Four things worth knowing
//!
//! **This driver contains zero `unsafe` and never dereferences the mapping.** A
//! client transfer is `SYS_SAFECOPY`, and even the boot self-check goes through
//! `SYS_COPY(SELF → SELF)` rather than a raw load. So a page the kernel failed to
//! map surfaces as an `EFAULT` *return value* from a kernel call — a better
//! diagnostic than TTY's equivalent, which would be an EL0 data abort — and there
//! is no MMIO sibling module and no new Sonar exclusion.
//!
//! **The granter comes from `m_source`.** This driver holds `SYS_SAFECOPY`; its
//! clients do not. A granter field in the payload would let any client aim a
//! privileged cross-address-space copy at a third party's memory through it.
//! `bdev.rs` has no way to express one.
//!
//! **An over-long or out-of-range request is `EINVAL`.** Not a short read (a
//! filesystem cannot interpret half a block) and not `EIO` (which stays reserved
//! for Phase 6's real media errors). See `bdev.rs`.
//!
//! **`BDEV_WRITE` answers `EROFS`, not `ENOSYS`.** `ENOSYS` is already the
//! unknown-`m_type` answer, so reusing it would make "never heard of writes" and
//! "knows about writes and refuses them" indistinguishable. Slice 5.10 changes one
//! line inside that arm.

// Freestanding for the real (bare-metal) build, but a normal host binary under
// `cargo test` so `bdev`'s logic gets host-runnable unit tests. The test harness
// needs `std` and its own entry point, so `no_std`/`no_main` and the `_start` shim
// below are all gated to `not(test)`.
#![cfg_attr(not(test), no_std)]
#![cfg_attr(not(test), no_main)]
#![forbid(unsafe_code)]

minixrs_abi_note::brand!();

mod bdev;

use minixrs_ipc::ipc_send;
use minixrs_kernel_shared::Message;
use minixrs_kernel_shared::callnr::{
    BDEV_BLOCK_SIZE, BDEV_READ, BDEV_WRITE, GET_RAMDISK, GETINFO_RAMDISK_LEN_OFF,
    GETINFO_RAMDISK_VA_OFF, SAFECOPY_TO, SYS_GETINFO_NAME_LEN,
};
use minixrs_kernel_shared::endpoint::{Endpoint, SELF};
use minixrs_kernel_shared::error::{ENOSYS, EROFS, OK};
use minixrs_kernel_shared::rootfs::{
    HDR_BLOCKS_OFF, IMAGE_HDR_LEN, IMAGE_LABEL, IMAGE_LABEL_LEN, IMAGE_TAIL_LABEL,
};
use minixrs_kernel_shared::uspace::RAMDISK_VA;
use minixrs_server_rt::{
    SefConfig, buf_addr, diag_fmt, rd_i32, rd_u64, sef_publish_to_ds, sef_startup, sys_copy,
    sys_getinfo, sys_safecopy,
};

/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start` can dive
/// straight into Rust without setting up a stack itself.
#[cfg(not(test))]
#[unsafe(no_mangle)]
#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
pub extern "C" fn _start() -> ! {
    main()
}

// Only `_start` calls `main`; under `cargo test` `_start` is gone, so `main` (and
// the helpers it alone reaches) would read as dead code.
#[cfg_attr(test, allow(dead_code))]
fn main() -> ! {
    let sef = sef_startup(SefConfig {
        init_fresh: Some(mem_init),
        signal_handler: None,
    })
    .unwrap_or_else(|_| {
        // No recovery and nothing to print: a failed handshake means this driver
        // never learned its own endpoint, so it cannot even announce the failure.
        loop {
            core::hint::spin_loop()
        }
    });

    // Where the ramdisk is, and how big. Locals in `main`'s frame — not statics,
    // and not `mem_init`'s frame, whose stack is gone by the time a client calls —
    // the same rule `GrantPool` and TTY's staging buffer follow.
    //
    // Deliberately *after* `sef_startup`, not inside `mem_init`: the kernel gates
    // `GET_RAMDISK` on the caller's proc number, so a failure here means the
    // kernel's pre-map arm and its getinfo gate disagree, and that is worth a
    // distinct diag line rather than an aborted startup.
    let (va, blocks) = ramdisk_geometry();

    let mut msg = Message {
        m_source: 0,
        m_type: 0,
        payload: [0u8; 96],
    };
    loop {
        if sef.receive(&mut msg) != OK {
            continue;
        }
        // Capture the caller *first*: it is both the reply target and the granter,
        // and the dispatch below overwrites `msg.m_source` on the way out.
        let caller_e = msg.m_source;
        match msg.m_type {
            BDEV_READ => {
                let rc = do_read(caller_e, &msg, va, blocks);
                reply(caller_e, &mut msg, rc);
            }
            // Defined and refused, rather than folded into the `_` arm below —
            // that difference is the whole reason `BDEV_WRITE` has a number.
            BDEV_WRITE => reply(caller_e, &mut msg, EROFS),
            // Unlike DS, reply rather than drop — the caller is inside a SENDREC
            // and would otherwise block forever.
            _ => reply(caller_e, &mut msg, ENOSYS),
        }
    }
}

/// SEF fresh-init callback: publish to DS. Nothing else — see [`ramdisk_geometry`]
/// for why the ramdisk lookup happens in `main`'s frame instead.
#[cfg_attr(test, allow(dead_code))]
fn mem_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
    sef_publish_to_ds(name)
}

/// Ask the kernel where the ramdisk is, check it over, and announce the result.
///
/// Returns `(va, blocks)`; on any failure it returns `(RAMDISK_VA, 0)`, which makes
/// every subsequent `BDEV_READ` fail its range check with `EINVAL` rather than
/// letting a bad geometry reach `SYS_SAFECOPY`. A zero-block device is exactly the
/// right degenerate state: clients hear "out of range" for every block.
#[cfg_attr(test, allow(dead_code))]
fn ramdisk_geometry() -> (u64, u64) {
    let mut msg = Message {
        m_source: 0,
        m_type: 0,
        payload: [0u8; 96],
    };
    let rc = sys_getinfo(GET_RAMDISK, &mut msg);
    if rc != OK {
        diag_fmt(format_args!("ramdisk FAIL getinfo rc={rc}"));
        return (RAMDISK_VA, 0);
    }
    let va = rd_u64(&msg, GETINFO_RAMDISK_VA_OFF);
    let len = rd_u64(&msg, GETINFO_RAMDISK_LEN_OFF);

    let blocks = match bdev::validate_geometry(len) {
        Ok(blocks) => blocks,
        Err(e) => {
            diag_fmt(format_args!("ramdisk FAIL geometry len={len} rc={e}"));
            return (va, 0);
        }
    };
    if selfcheck(va, len, blocks) { (va, blocks) } else { (va, 0) }
}

/// Prove the mapping is real, complete, and holds the image this build packed.
///
/// Two 32-byte reads through `SYS_COPY(SELF → SELF)`, which the kernel supports
/// (`do_copy` short-circuits `SELF` for both endpoints, and `copy_between_as` over
/// two disjoint ranges of one address space is an ordinary copy). Going through a
/// kernel call rather than dereferencing keeps this driver `forbid(unsafe_code)`
/// and turns an unmapped page into an errno instead of a fault.
///
/// The **head** read checks the image label and cross-checks the header's own
/// block count against the length the kernel reported — binding mkfs's geometry to
/// the kernel's copy, two independently derived numbers.
///
/// The **tail** read is the one that earns its keep. It reads the reserved last
/// block, whose label deliberately differs from the header's, so a kernel copy loop
/// that failed to advance — mapping 256 pages of block 0 — fails here while every
/// header check still passes. Nothing else in the boot proves the copy reached the
/// end of the blob.
///
/// Deliberately a *device*-level check: no superblock is decoded and
/// `minixrs-mfs` is not a dependency, because a block driver must not depend on
/// the filesystem format. `tools/mkfs-mfs`'s round trip is what proves the header
/// cannot disagree with the real superblock.
#[cfg_attr(test, allow(dead_code))]
fn selfcheck(va: u64, len: u64, blocks: u64) -> bool {
    let mut buf = [0u8; IMAGE_HDR_LEN];

    let rc = sys_copy(SELF, va, SELF, buf_addr(&mut buf), IMAGE_HDR_LEN as u64);
    if rc != OK {
        diag_fmt(format_args!("ramdisk FAIL head rc={rc}"));
        return false;
    }
    if buf[..IMAGE_LABEL_LEN] != IMAGE_LABEL {
        diag_fmt(format_args!("ramdisk FAIL label"));
        return false;
    }
    let hdr_blocks = rd_hdr_u32(&buf, HDR_BLOCKS_OFF);
    if u64::from(hdr_blocks) != blocks {
        diag_fmt(format_args!(
            "ramdisk FAIL blocks hdr={hdr_blocks} dev={blocks}"
        ));
        return false;
    }

    // `len` is a whole number of blocks and non-zero (validate_geometry), so this
    // subtraction cannot underflow and names the last block's first byte.
    let tail_va = va + len - BDEV_BLOCK_SIZE as u64;
    let rc = sys_copy(SELF, tail_va, SELF, buf_addr(&mut buf), IMAGE_HDR_LEN as u64);
    if rc != OK {
        diag_fmt(format_args!("ramdisk FAIL tail rc={rc}"));
        return false;
    }
    if buf[..IMAGE_LABEL_LEN] != IMAGE_TAIL_LABEL {
        diag_fmt(format_args!("ramdisk FAIL tail label"));
        return false;
    }

    diag_fmt(format_args!("ramdisk ok blocks={blocks} tail=1"));
    true
}

/// Read a little-endian `u32` out of the image header. The header is written by
/// `tools/mkfs-mfs` on a little-endian host for a little-endian target — the same
/// assumption the MXBI archive already makes — so this is `from_le_bytes` rather
/// than one of `server-rt`'s native-endian payload accessors, which describe
/// *message* fields.
fn rd_hdr_u32(buf: &[u8; IMAGE_HDR_LEN], off: usize) -> u32 {
    u32::from_le_bytes([buf[off], buf[off + 1], buf[off + 2], buf[off + 3]])
}

/// Serve one `BDEV_READ`. Returns the reply `m_type`: the byte count read
/// (`>= 0`), or a negative errno.
#[cfg_attr(test, allow(dead_code))]
fn do_read(caller_e: Endpoint, msg: &Message, va: u64, blocks: u64) -> i32 {
    let req = bdev::parse_read(msg);
    let (byte_off, n) = match bdev::validate_read(req, blocks) {
        Ok(v) => v,
        Err(e) => return e,
    };
    if n == 0 {
        // A legal zero-length read. No grant is used and nothing is copied, so a
        // client polling with `len = 0` cannot use it to probe a grant.
        return 0;
    }

    // Push the bytes into the client's granted buffer. `caller_e` is the
    // kernel-stamped source of this very message — the granter can be nothing else.
    //
    // The grant offset is `0`, not a payload field: `BDEV_READ` deliberately has
    // none, because every client through slice 5.9 grants a buffer whose block
    // starts at its beginning.
    let rc = sys_safecopy(SAFECOPY_TO, caller_e, req.gid, 0, va + byte_off, n as u64);
    if rc != OK {
        // Verbatim: EPERM ("your grant does not authorize this") and EFAULT ("your
        // buffer is not mapped") are different bugs on the client's side.
        return rc;
    }
    n as i32
}

/// Reply to a SENDREC caller: stamp `m_type`, zero `m_source` (the kernel
/// overwrites it on delivery), and SEND the message back. A copy of TTY's, for the
/// reason TTY's exists.
#[cfg_attr(test, allow(dead_code))]
fn reply(target_e: Endpoint, msg: &mut Message, m_type: i32) {
    msg.m_type = m_type;
    msg.m_source = 0;
    let _ = ipc_send(target_e, msg);
}

// `rd_i32` is re-exported by `server-rt` and used by `bdev.rs`; naming it here
// keeps the import list honest about what this crate pulls in.
#[cfg_attr(test, allow(dead_code))]
const _: fn(&Message, usize) -> i32 = rd_i32;

// The freestanding panic handler; under `cargo test` std supplies its own.
#[cfg(not(test))]
#[panic_handler]
fn panic(_: &core::panic::PanicInfo) -> ! {
    loop {
        core::hint::spin_loop()
    }
}

